  const role = ROLES[ctx.lanes[li].role];
  const disp = rng.gauss() * ctx.p.looseness * 0.02 * (att.family === 'main' ? 1 : 0.6);
  const accent = rng.chance(role.accentP * role.accentWeight(att, ctx.meter)) ? rng.range(0.5, 1) : 0;
